export function roomOptions(capacity){return `<div class="room-options" role="radiogroup" aria-label="选择寝室人数">${[4,6].map(n=>`<label class="room-option ${capacity===n?'chosen':''}"><input type="radio" name="room-capacity" value="${n}" ${capacity===n?'checked':''}><span class="mini-floor beds-${n}">${Array.from({length:n},()=>'<i class="mini-bed"></i>').join('')}</span><span class="room-option-title">${n} 人寝 <b>${capacity===n?'已选择':'选择'}</b></span><small>${n===6?'六个床位，六位室友':'四个床位，温馨小空间'}</small></label>`).join('')}</div>`;}
export function waitOptions(minutes){return `<div class="wait-presets" role="group" aria-label="常用等待时间">${[5,10,15,30].map(n=>`<button type="button" data-wait-preset="${n}" class="${minutes===n?'chosen':''}">${n} 分钟${n===15?'<small>默认</small>':''}</button>`).join('')}</div><label class="custom-wait">自定义等待时间<span><input name="wait-minutes" type="number" min="1" max="60" step="1" value="${minutes}" required aria-label="自定义等待时间">分钟</span></label><p class="input-hint">支持 1～60 分钟。修改后，进行中的倒计时会重新开始。</p>`;}
export function irLesson(captured){return `<div class="ir-tutorial-art ${captured?'captured':''}" role="img" aria-label="原遥控器对准控制盒上的红外接收头"><div class="tutorial-remote"><span>原遥控器</span><div>OFF</div><i></i><b>⏻</b></div><div class="tutorial-signal"><i></i><i></i><i></i><small>${captured?'已收到模拟信号':'对准红外接收头'}</small></div><div class="tutorial-receiver"><i></i><b>栖息</b><span>学习接收头</span></div></div><ol class="tutorial-points"><li><strong>先学信号</strong><span>把原遥控器对准控制盒的接收头，采集两次关机信号。</span></li><li><strong>再试三次</strong><span>开着能关、关了不再开、换一个运行设置仍能关，才是可靠的 OFF。</span></li><li><strong>最后固定</strong><span>把发射头放在空调接收窗附近。完整学习后，要重新校准人数。</span></li></ol>`;}

export class SetupWizard {
  constructor({getSettings,onSave}){this.getSettings=getSettings;this.onSave=onSave;this.root=document.createElement('div');this.root.id='setup-layer';document.body.append(this.root);this.step=0;this.draft=null;this.captured=false;this.replay=false;this.active=false;}
  open(replay=false){if(this.active)return;this.step=0;this.draft={...this.getSettings()};this.captured=false;this.replay=replay;this.active=true;this.trigger=document.activeElement;this.render();}
  close(){this.root.querySelector('dialog')?.close();this.root.replaceChildren();this.active=false;if(this.trigger?.isConnected)this.trigger.focus({preventScroll:true});}
  render(){
    const titles=['先认识一下，你的宿舍','让空调听懂「关机」','多久没人，自动关机？'];
    const subtitles=['选好房型，房间示意和成员数量会一起调整。','用一个小教程，了解红外遥控的配对流程。','设定等待时间；期间可提前确认，不确认也会到点关闭。'];
    const previous=this.root.querySelector('dialog');if(previous)previous.close();
    const body=this.step===0?`${roomOptions(this.draft.roomCapacity)}<div class="note">床位数不等于当前人数。入住设置只改变房间布局，实际人数仍需校准。</div>`:this.step===1?`${irLesson(this.captured)}<button type="button" class="btn ${this.captured?'secondary':'primary'} full" data-setup="capture">${this.captured?'✓ 已收到模拟 OFF，点击可再试一次':'试一下：模拟按遥控器关机'}</button><p class="input-hint">教程只模拟收码，不表示已对真实空调完成配对。</p>`:`${waitOptions(this.draft.waitMinutes)}<div class="rule-preview"><span>空房并关门</span><i>→</i><strong>等待 <b id="setup-wait-preview">${this.draft.waitMinutes}</b> 分钟</strong><i>→</i><span>自动关机</span></div><div class="note"><strong>可提前确认，到点自动执行。</strong><br>置顶提醒中选择“立即确认关机”会提前执行；选择“继续等待”或不操作，到预设时间仍会自动关机。选择“暂停本次关机”才会停止本次任务。</div><p class="phone-onboarding-tip">进入宿舍后，点击右上角铃铛，可查看“添加到手机桌面”和通知设置教程。此处不会申请通知权限。</p>`;
    this.root.innerHTML=`<dialog class="modal onboarding-modal" aria-labelledby="setup-title" aria-describedby="setup-description"><div class="setup-top"><a class="setup-brand">栖息 <small>QIXI</small></a><span>首次使用 · ${this.step+1} / 3</span>${this.replay?'<button class="icon-btn" data-setup="close" aria-label="关闭新手引导">×</button>':''}</div><div class="setup-progress">${['确认房型','红外教程','等待时间'].map((n,i)=>`<span class="${i===this.step?'current':i<this.step?'done':''}"><i>${i<this.step?'✓':i+1}</i>${n}</span>`).join('')}</div><h2 id="setup-title">${titles[this.step]}</h2><p class="dialog-intro" id="setup-description">${subtitles[this.step]}</p><form id="setup-form">${body}<p class="setup-error" role="alert"></p><div class="setup-footer">${this.step?'<button type="button" class="btn secondary" data-setup="back">上一步</button>':'<span>仅需一分钟，之后也能修改</span>'}<button type="submit" class="btn primary">${this.step===2?'保存设置，进入宿舍':'下一步'}</button></div></form></dialog>`;
    const d=this.root.querySelector('dialog');d.addEventListener('cancel',e=>{e.preventDefault();if(this.replay)this.close();});
    d.addEventListener('change',e=>{if(e.target.name==='room-capacity'){this.draft.roomCapacity=Number(e.target.value);this.render();this.root.querySelector(`input[value="${this.draft.roomCapacity}"]`)?.focus();}});
    d.addEventListener('input',e=>{if(e.target.name==='wait-minutes'){this.draft.waitMinutes=Number(e.target.value);this.root.querySelector('#setup-wait-preview').textContent=e.target.value||'—';this.root.querySelectorAll('[data-wait-preset]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.waitPreset)===this.draft.waitMinutes));}});
    d.addEventListener('click',e=>{const preset=e.target.closest('[data-wait-preset]');if(preset){this.draft.waitMinutes=Number(preset.dataset.waitPreset);this.render();this.root.querySelector(`[data-wait-preset="${this.draft.waitMinutes}"]`).focus();return;}const b=e.target.closest('[data-setup]');if(!b)return;const a=b.dataset.setup;if(a==='back'){this.step--;this.render();}if(a==='capture'){this.captured=true;this.render();this.root.querySelector('[data-setup="capture"]').focus();}if(a==='close')this.close();});
    d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(this.step===1&&!this.captured){d.querySelector('.setup-error').textContent='先点一下“模拟按遥控器关机”，体验接收信号。';return;}if(this.step<2){this.step++;this.render();}else if(this.onSave({...this.draft,onboardingDone:true})){this.close();}else d.querySelector('.setup-error').textContent='请等待当前操作完成后重试，时间需为 1～60 的整数。';});
    d.showModal();
  }
}
